use std::io::{self, Read, Write};

const LIMIT: i128 = 1_000_000_000_000;
const ROWS: usize = 20;
const CELLS: usize = 10 * ROWS;
const VALUE_ERR: &str = "#VALUE";
const DIV0_ERR: &str = "#DIV0";
const OVERFLOW_ERR: &str = "#OVERFLOW";
const BAD_COMMAND: &str = "error: bad command";
const BAD_FORMULA: &str = "error: bad formula";

#[derive(Clone, Copy)]
enum Func {
    Sum,
    Min,
    Max,
    Count,
    Abs,
}

#[derive(Clone, Copy)]
struct Rect {
    c1: usize,
    r1: usize,
    c2: usize,
    r2: usize,
}

impl Rect {
    // Row-major order: rows outer, columns inner.
    fn cells(&self) -> Vec<usize> {
        (self.r1..=self.r2)
            .flat_map(|r| (self.c1..=self.c2).map(move |c| c * ROWS + r))
            .collect()
    }
}

#[derive(Clone)]
enum Arg {
    Range(Rect),
    Scalar(Expr),
}

#[derive(Clone)]
enum Expr {
    Num(i64),
    Ref(usize),
    Neg(Box<Expr>),
    Bin(u8, Box<Expr>, Box<Expr>),
    Call(Func, Vec<Arg>),
}

#[derive(Clone)]
enum Content {
    Num(i64),
    Text(String),
    Formula(Expr),
}

#[derive(Clone, PartialEq)]
enum Tok {
    Num(i64),
    Word(String),
    Sym(u8),
}

// Cell index is column-major, so sorting indices gives column then row order.
fn parse_cell(s: &str) -> Option<usize> {
    let b = s.as_bytes();
    if b.len() < 2 || b.len() > 3 || !(b'A'..=b'J').contains(&b[0]) {
        return None;
    }
    if b[1] == b'0' || !b[1..].iter().all(u8::is_ascii_digit) {
        return None;
    }
    let row: usize = s[1..].parse().ok()?;
    if !(1..=ROWS).contains(&row) {
        return None;
    }
    Some((b[0] - b'A') as usize * ROWS + row - 1)
}

fn cell_name(idx: usize) -> String {
    format!("{}{}", (b'A' + (idx / ROWS) as u8) as char, idx % ROWS + 1)
}

fn rect_of(a: usize, b: usize) -> Rect {
    Rect {
        c1: (a / ROWS).min(b / ROWS),
        r1: (a % ROWS).min(b % ROWS),
        c2: (a / ROWS).max(b / ROWS),
        r2: (a % ROWS).max(b % ROWS),
    }
}

fn func_named(w: &str) -> Option<Func> {
    match w {
        "SUM" => Some(Func::Sum),
        "MIN" => Some(Func::Min),
        "MAX" => Some(Func::Max),
        "COUNT" => Some(Func::Count),
        "ABS" => Some(Func::Abs),
        _ => None,
    }
}

fn is_number(s: &str) -> bool {
    let digits = s.strip_prefix('-').unwrap_or(s);
    !digits.is_empty() && digits.len() <= 9 && digits.bytes().all(|b| b.is_ascii_digit())
}

fn tokenize(s: &str) -> Option<Vec<Tok>> {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == b' ' {
            i += 1;
        } else if c.is_ascii_digit() {
            let start = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            if i - start > 9 {
                return None;
            }
            out.push(Tok::Num(s[start..i].parse().ok()?));
        } else if c.is_ascii_alphabetic() {
            let start = i;
            while i < b.len() && b[i].is_ascii_alphanumeric() {
                i += 1;
            }
            out.push(Tok::Word(s[start..i].to_string()));
        } else if b"+-*/(),:".contains(&c) {
            out.push(Tok::Sym(c));
            i += 1;
        } else {
            return None;
        }
    }
    Some(out)
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
}

impl Parser {
    fn peek_sym(&self, c: u8) -> bool {
        self.toks.get(self.pos) == Some(&Tok::Sym(c))
    }

    fn eat_sym(&mut self, c: u8) -> Option<()> {
        if self.peek_sym(c) {
            self.pos += 1;
            Some(())
        } else {
            None
        }
    }

    fn expr(&mut self) -> Option<Expr> {
        let mut left = self.term()?;
        loop {
            let op = if self.peek_sym(b'+') {
                b'+'
            } else if self.peek_sym(b'-') {
                b'-'
            } else {
                break;
            };
            self.pos += 1;
            let right = self.term()?;
            left = Expr::Bin(op, Box::new(left), Box::new(right));
        }
        Some(left)
    }

    fn term(&mut self) -> Option<Expr> {
        let mut left = self.unary()?;
        loop {
            let op = if self.peek_sym(b'*') {
                b'*'
            } else if self.peek_sym(b'/') {
                b'/'
            } else {
                break;
            };
            self.pos += 1;
            let right = self.unary()?;
            left = Expr::Bin(op, Box::new(left), Box::new(right));
        }
        Some(left)
    }

    fn unary(&mut self) -> Option<Expr> {
        if self.eat_sym(b'-').is_some() {
            Some(Expr::Neg(Box::new(self.unary()?)))
        } else {
            self.primary()
        }
    }

    fn primary(&mut self) -> Option<Expr> {
        let tok = self.toks.get(self.pos)?.clone();
        self.pos += 1;
        match tok {
            Tok::Num(n) => Some(Expr::Num(n)),
            Tok::Sym(b'(') => {
                let e = self.expr()?;
                self.eat_sym(b')')?;
                Some(e)
            }
            Tok::Word(w) => {
                if let Some(func) = func_named(&w) {
                    self.eat_sym(b'(')?;
                    let mut args = vec![self.arg()?];
                    while self.eat_sym(b',').is_some() {
                        args.push(self.arg()?);
                    }
                    self.eat_sym(b')')?;
                    let arity_ok = match func {
                        Func::Abs => args.len() == 1 && matches!(args[0], Arg::Scalar(_)),
                        _ => true,
                    };
                    if !arity_ok {
                        return None;
                    }
                    Some(Expr::Call(func, args))
                } else {
                    Some(Expr::Ref(parse_cell(&w)?))
                }
            }
            _ => None,
        }
    }

    fn arg(&mut self) -> Option<Arg> {
        if let (Some(Tok::Word(a)), Some(Tok::Sym(b':')), Some(Tok::Word(c))) = (
            self.toks.get(self.pos),
            self.toks.get(self.pos + 1),
            self.toks.get(self.pos + 2),
        ) {
            if let (Some(x), Some(y)) = (parse_cell(a), parse_cell(c)) {
                self.pos += 3;
                return Some(Arg::Range(rect_of(x, y)));
            }
        }
        Some(Arg::Scalar(self.expr()?))
    }
}

fn parse_formula(src: &str) -> Option<Expr> {
    let mut p = Parser {
        toks: tokenize(src)?,
        pos: 0,
    };
    let e = p.expr()?;
    if p.pos == p.toks.len() {
        Some(e)
    } else {
        None
    }
}

fn expr_deps(e: &Expr, out: &mut Vec<usize>) {
    match e {
        Expr::Num(_) => {}
        Expr::Ref(i) => out.push(*i),
        Expr::Neg(x) => expr_deps(x, out),
        Expr::Bin(_, a, b) => {
            expr_deps(a, out);
            expr_deps(b, out);
        }
        Expr::Call(_, args) => {
            for arg in args {
                match arg {
                    Arg::Range(rect) => out.extend(rect.cells()),
                    Arg::Scalar(x) => expr_deps(x, out),
                }
            }
        }
    }
}

fn deps_sorted(e: &Expr) -> Vec<usize> {
    let mut v = Vec::new();
    expr_deps(e, &mut v);
    v.sort_unstable();
    v.dedup();
    v
}

fn bound(v: i128) -> Result<i64, &'static str> {
    if v.abs() > LIMIT {
        Err(OVERFLOW_ERR)
    } else {
        Ok(v as i64)
    }
}

struct Sheet {
    cells: Vec<Option<Content>>,
}

impl Sheet {
    fn eval_cell(&self, idx: usize) -> Result<i64, &'static str> {
        match &self.cells[idx] {
            None => Ok(0),
            Some(Content::Num(n)) => Ok(*n),
            Some(Content::Text(_)) => Err(VALUE_ERR),
            Some(Content::Formula(e)) => self.eval(e),
        }
    }

    fn eval(&self, e: &Expr) -> Result<i64, &'static str> {
        match e {
            Expr::Num(n) => Ok(*n),
            Expr::Ref(idx) => self.eval_cell(*idx),
            Expr::Neg(x) => Ok(-self.eval(x)?),
            Expr::Bin(op, a, b) => {
                let x = self.eval(a)? as i128;
                let y = self.eval(b)? as i128;
                match op {
                    b'+' => bound(x + y),
                    b'-' => bound(x - y),
                    b'*' => bound(x * y),
                    _ => {
                        if y == 0 {
                            Err(DIV0_ERR)
                        } else {
                            bound(x / y)
                        }
                    }
                }
            }
            Expr::Call(func, args) => {
                let mut vals: Vec<i64> = Vec::new();
                for arg in args {
                    match arg {
                        Arg::Scalar(x) => vals.push(self.eval(x)?),
                        Arg::Range(rect) => {
                            for idx in rect.cells() {
                                if matches!(self.cells[idx], None | Some(Content::Text(_))) {
                                    continue;
                                }
                                vals.push(self.eval_cell(idx)?);
                            }
                        }
                    }
                }
                match func {
                    Func::Abs => Ok(vals[0].abs()),
                    Func::Count => Ok(vals.len() as i64),
                    Func::Sum => {
                        let mut acc: i64 = 0;
                        for v in vals {
                            acc = bound(acc as i128 + v as i128)?;
                        }
                        Ok(acc)
                    }
                    Func::Min => vals.iter().min().copied().ok_or(VALUE_ERR),
                    Func::Max => vals.iter().max().copied().ok_or(VALUE_ERR),
                }
            }
        }
    }

    fn show(&self, idx: usize) -> String {
        match &self.cells[idx] {
            None => "(empty)".to_string(),
            Some(Content::Text(t)) => t.clone(),
            _ => match self.eval_cell(idx) {
                Ok(n) => n.to_string(),
                Err(e) => e.to_string(),
            },
        }
    }

    // Depth-first search from `search` along dependencies; returns the first
    // path that gets back to `x`.
    fn search(
        &self,
        x: usize,
        deps: &[usize],
        visited: &mut [bool; CELLS],
        path: &mut Vec<usize>,
    ) -> Option<Vec<usize>> {
        for &d in deps {
            if d == x {
                let mut found = path.clone();
                found.push(x);
                return Some(found);
            }
            if visited[d] {
                continue;
            }
            visited[d] = true;
            path.push(d);
            let next = match &self.cells[d] {
                Some(Content::Formula(e)) => deps_sorted(e),
                _ => Vec::new(),
            };
            if let Some(found) = self.search(x, &next, visited, path) {
                return Some(found);
            }
            path.pop();
        }
        None
    }

    fn set(&mut self, idx: usize, content: &str) -> Result<(), String> {
        let new = if let Some(src) = content.strip_prefix('=') {
            let expr = parse_formula(src).ok_or_else(|| BAD_FORMULA.to_string())?;
            let deps = deps_sorted(&expr);
            let mut visited = [false; CELLS];
            if let Some(cycle) = self.search(idx, &deps, &mut visited, &mut vec![idx]) {
                let names: Vec<String> = cycle.iter().map(|&i| cell_name(i)).collect();
                return Err(format!("error: cycle {}", names.join(" -> ")));
            }
            Content::Formula(expr)
        } else if is_number(content) {
            Content::Num(content.parse().unwrap())
        } else {
            Content::Text(content.to_string())
        };
        self.cells[idx] = Some(new);
        Ok(())
    }
}

fn run(sheet: &mut Sheet, line: &str, out: &mut String) {
    if let Some(rest) = line.strip_prefix("set ") {
        let parsed = rest.split_once(' ').and_then(|(c, content)| {
            let idx = parse_cell(c)?;
            (!content.is_empty()).then_some((idx, content))
        });
        match parsed {
            None => out.push_str(&format!("{}\n", BAD_COMMAND)),
            Some((idx, content)) => {
                if let Err(msg) = sheet.set(idx, content) {
                    out.push_str(&format!("{}\n", msg));
                }
            }
        }
        return;
    }
    let words: Vec<&str> = line.split_whitespace().collect();
    match words.as_slice() {
        ["get", c] => match parse_cell(c) {
            Some(idx) => out.push_str(&format!("{} = {}\n", cell_name(idx), sheet.show(idx))),
            None => out.push_str(&format!("{}\n", BAD_COMMAND)),
        },
        ["clear", c] => match parse_cell(c) {
            Some(idx) => sheet.cells[idx] = None,
            None => out.push_str(&format!("{}\n", BAD_COMMAND)),
        },
        ["dump"] => {
            if sheet.cells.iter().all(Option::is_none) {
                out.push_str("(empty sheet)\n");
            }
            for idx in 0..CELLS {
                if sheet.cells[idx].is_some() {
                    out.push_str(&format!("{} = {}\n", cell_name(idx), sheet.show(idx)));
                }
            }
        }
        _ => out.push_str(&format!("{}\n", BAD_COMMAND)),
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut sheet = Sheet {
        cells: vec![None; CELLS],
    };
    let mut out = String::new();
    for line in input.lines() {
        let line = line.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        run(&mut sheet, line, &mut out);
    }
    io::stdout().write_all(out.as_bytes()).unwrap();
}
